(() => {
  const page = document.body.dataset.verityPage || "dashboard";
  const content = document.querySelector("#va-content");
  const picker = document.querySelector("#va-workspace");
  const notice = document.querySelector("#va-notice");
  let workspace = null;
  let leadFilters = {start:0, limit:20, status:"", source_channel:"", search:""};
  let conversationFilters = {start:0, limit:20, platform:"", status:"", search:""};
  let analyticsFilters = {from_date:"", to_date:""};
  let commerceView = "overview";

  const guidedSteps = [
    {route:"assistant", label:"Assistant", title:"Assistant profile", codes:["assistant","business_nature"]},
    {route:"widget", label:"Website widget", title:"Widget and domains", codes:["widget","domain"]},
    {route:"knowledge", label:"Knowledge", title:"Knowledge sources", codes:["knowledge"]},
    {route:"email", label:"Email", title:"Email notifications", codes:["email"]},
    {route:"whatsapp", label:"WhatsApp", title:"WhatsApp channel", codes:["whatsapp"]},
    {route:"onboarding", label:"Review", title:"Launch review", codes:[]},
  ];

  const esc = (value) => String(value ?? "").replace(/[&<>'"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
  const number = (value) => new Intl.NumberFormat().format(Number(value || 0));
  const pill = (value) => `<span class="va-pill ${["Active","Connected","Done","Normal","Trial","Healthy","Approved","Won"].includes(value)?"good":["Failed","Suspended","Exhausted","Critical","Lost","Cancelled"].includes(value)?"bad":""}">${esc(value || "—")}</span>`;
  const field = (label, name, value="", type="text", full=false) => `<div class="va-field ${full?"full":""}"><label>${esc(label)}</label>${type==="textarea"?`<textarea name="${name}">${esc(value)}</textarea>`:`<input type="${type}" name="${name}" value="${esc(value)}">`}</div>`;
  const selectField = (label,name,options,value="",placeholder="Choose an option",full=false) => `<div class="va-field ${full?"full":""}"><label>${esc(label)}</label><select name="${name}" required><option value="">${esc(placeholder)}</option>${options.map(option=>`<option value="${esc(option.value)}" ${option.value===value?"selected":""}>${esc(option.label)}</option>`).join("")}</select></div>`;
  const json = (form) => Object.fromEntries(new FormData(form).entries());
  const routeUrl = (route, guided=false) => `/verityai/${route}?workspace=${encodeURIComponent(workspace)}${guided?"&guided=1":""}`;
  const isGuided = () => new URLSearchParams(location.search).get("guided") === "1";
  const guidedIndex = () => guidedSteps.findIndex(step=>step.route===page);
  const guidedNav = () => {
    if(!isGuided()) return "";
    const index=guidedIndex();
    if(index<0) return "";
    const previous=index>0?guidedSteps[index-1]:null;
    const next=index<guidedSteps.length-1?guidedSteps[index+1]:null;
    return `<nav class="va-guided-nav" aria-label="Setup journey"><div><span>Guided setup</span><strong>Step ${index+1} of ${guidedSteps.length} · ${esc(guidedSteps[index].label)}</strong></div><div class="va-actions">${previous?`<a class="va-button ghost" href="${routeUrl(previous.route,true)}">Back</a>`:""}${next?`<a class="va-button secondary" href="${routeUrl(next.route,true)}">Continue</a>`:`<a class="va-button" href="${routeUrl("dashboard")}">Finish setup</a>`}</div></nav>`;
  };
  const showGuidedNav = () => content.insertAdjacentHTML("beforeend", guidedNav());
  const continueGuided = route => { if(isGuided()) location.assign(routeUrl(route,true)); };

  const natureProfile = (name,natures) => {
    const nature=(natures||[]).find(row=>row.business_nature===name);
    if(!nature)return `<div class="va-context-panel"><p class="muted">Select a business nature to load a tailored sales discovery profile.</p></div>`;
    const questions=(nature.lead_fields||[]).map(row=>`<span class="va-question-chip">${esc(row.label)}${row.required?' <b>Required</b>':''}</span>`).join("");
    return `<div class="va-context-panel"><div><p class="eyebrow">Sales discovery profile</p><h3>${esc(nature.business_nature)}</h3><p class="muted">${esc(nature.description||"")}</p></div><div class="va-question-list">${questions}</div></div>`;
  };

  async function call(method, args={}) {
    const body = new FormData();
    Object.entries(args).forEach(([key,value]) => body.append(key, typeof value === "object" ? JSON.stringify(value) : value ?? ""));
    const response = await fetch(`/api/method/${method}`, {method:"POST", headers:{"X-Frappe-CSRF-Token":window.csrf_token || ""}, body});
    let payload;
    try { payload=await response.json(); }
    catch(error) { throw new Error(`Server returned an unreadable response (HTTP ${response.status}).`); }
    const result = payload.message || payload;
    if (!response.ok || !result.success) {
      const type=payload.exc_type || result.code || "";
      const expired=type.includes("CSRF") || response.status===401;
      throw new Error(result.error || (expired?"Your session expired. Refresh the page and sign in again.":`Server request failed${response.status?` (HTTP ${response.status})`:""}.`));
    }
    return result.data;
  }

  async function uploadPrivateFile(file) {
    const body=new FormData(); body.append("file",file); body.append("is_private","1"); body.append("folder","Home/Attachments");
    const response=await fetch("/api/method/upload_file",{method:"POST",headers:{"X-Frappe-CSRF-Token":window.csrf_token||""},body});
    const payload=await response.json(); const result=payload.message||payload;
    if(!response.ok||!result.name)throw new Error(result.exception||result.message||"Private file upload failed");
    return result.name;
  }
  function alert(message, error=false) {
    notice.textContent = message; notice.className = `va-notice ${error?"error":""}`; notice.hidden = false;
    window.setTimeout(() => notice.hidden = true, 5000);
  }

  const barChart = (rows, key, label) => {
    const maximum=Math.max(...rows.map(row=>Number(row[key]||0)),1);
    return `<div class="va-card"><h2>${esc(label)}</h2><div class="va-bar-chart">${rows.map(row=>`<div class="va-bar-column" title="${esc(row.date)}: ${number(row[key])}"><i style="height:${Math.max(Number(row[key]||0)*100/maximum,2)}%"></i><span>${esc(row.date.slice(5))}</span></div>`).join("")}</div></div>`;
  };
  const emptyState = (title="Nothing here yet", description="New records will appear here once they are created.", action="") => `<div class="va-empty"><span class="va-empty-icon" aria-hidden="true">+</span><div><strong>${esc(title)}</strong><p>${esc(description)}</p></div>${action}</div>`;
  const table = (columns, rows, empty={}) => rows.length ? `<div class="va-table-wrap"><table class="va-table"><thead><tr>${columns.map(c=>`<th>${esc(c[0])}</th>`).join("")}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map(c=>`<td data-label="${esc(c[0])}">${c[1](row)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>` : emptyState(empty.title,empty.description,empty.action||"");
  const section = (title, description, body, actions="") => `<section class="va-section"><header class="va-section-heading"><div><h2>${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:""}</div>${actions?`<div class="va-actions">${actions}</div>`:""}</header>${body}</section>`;

  async function dashboard() {
    const d = await call("verityai_saas.api.workspace.get", {workspace});
    const resume=Number(d.workspace.setup_progress||0)<100?`<div class="va-callout info va-setup-resume"><strong>Setup ${number(d.workspace.setup_progress)}% complete</strong><a class="va-button" href="${routeUrl("onboarding",true)}">Continue setup</a></div>`:"";
    content.innerHTML = `${resume}<div class="va-grid"><div class="va-card va-metric"><span>Setup progress</span><strong>${number(d.workspace.setup_progress)}%</strong><div class="va-progress"><i style="width:${Number(d.workspace.setup_progress||0)}%"></i></div></div><div class="va-card va-metric"><span>Conversations</span><strong>${number(d.conversation_count)}</strong></div><div class="va-card va-metric"><span>New leads</span><strong>${number(d.new_leads)}</strong></div><div class="va-card va-metric"><span>AI credits remaining</span><strong>${number(d.wallet.tokens_remaining)}</strong></div></div><div class="va-grid two"><div class="va-card"><h2>Workspace health</h2><p>${pill(d.workspace.status)} ${pill(d.wallet.status)}</p><p class="muted">${d.recent_alerts.length ? esc(d.recent_alerts[0].summary) : "No recent alerts."}</p></div><div class="va-card"><h2>Current plan</h2><p><strong>${esc(d.subscription?.plan || "No plan")}</strong></p><p class="muted">${esc(d.subscription?.status || "Not configured")}</p></div></div>`;
  }

  async function health(filters={}) {
    const d = await call("verityai_saas.api.health.get", {workspace, ...filters});
    const subscription = d.subscription || {};
    const wallet = d.wallet || {};
    const whatsapp = d.whatsapp || {};
    content.innerHTML = `<div class="va-grid"><div class="va-card va-metric"><span>Overall health</span><strong>${pill(d.overall_status)}</strong></div><div class="va-card va-metric"><span>Open alerts</span><strong>${number(d.open_alerts)}</strong></div><div class="va-card va-metric"><span>Critical alerts</span><strong>${number(d.critical_alerts)}</strong></div><div class="va-card va-metric"><span>Total alerts</span><strong>${number(d.total_alerts)}</strong></div></div><div class="va-grid two"><div class="va-card"><h2>Services</h2><p>Workspace ${pill(d.workspace_status)}</p><p>Assistant ${pill(d.engine_active?"Active":"Inactive")}</p><p>Monitoring ${pill(d.monitoring_enabled?"Active":"Disabled")}</p></div><div class="va-card"><h2>Account health</h2><p>Subscription ${pill(subscription.status||"Not configured")}</p><p>Usage wallet ${pill(wallet.status||"Not configured")}</p><p>WhatsApp ${pill(whatsapp.setup_status||"Not configured")}</p></div></div><form id="health-filter" class="va-card va-form"><h2>Alert history</h2><div class="va-fields"><div class="va-field"><label>Status</label><select name="status"><option value="">All statuses</option>${["Open","Acknowledged","Resolved"].map(value=>`<option ${filters.status===value?"selected":""}>${value}</option>`).join("")}</select></div><div class="va-field"><label>Severity</label><select name="severity"><option value="">All severities</option>${["Critical","Warning","Info"].map(value=>`<option ${filters.severity===value?"selected":""}>${value}</option>`).join("")}</select></div></div><button class="va-button secondary">Apply filters</button></form>${table([["Alert",r=>`<strong>${esc(r.summary||r.alert_type)}</strong><br><span class="muted">${esc(r.alert_type||"")}</span>`],["Severity",r=>pill(r.severity)],["Status",r=>pill(r.status)],["Occurrences",r=>number(r.occurrence_count)],["Last seen",r=>esc(r.last_seen||r.creation)]],d.alerts)}`;
    document.querySelector("#health-filter").addEventListener("submit", event => { event.preventDefault(); health(json(event.currentTarget)); });
  }
  async function onboarding() {
    const d = await call("verityai_saas.api.workspace.get", {workspace});
    const statuses=Object.fromEntries((d.checklist||[]).map(row=>[row.step_code,row.status]));
    const cards=guidedSteps.slice(0,-1).map((step,index)=>{
      const complete=step.codes.every(code=>statuses[code]==="Done");
      return `<a class="va-journey-step ${complete?"complete":""}" href="${routeUrl(step.route,true)}"><span>${complete?"✓":index+1}</span><strong>${esc(step.title)}</strong>${pill(complete?"Done":"Continue")}</a>`;
    }).join("");
    const pending=guidedSteps.slice(0,-1).find(step=>!step.codes.every(code=>["Done","Skipped"].includes(statuses[code])));
    content.innerHTML = `<section class="va-setup-hero"><div><p class="eyebrow">Setup</p><h2>Launch your assistant</h2></div><div><strong>${number(d.workspace.setup_progress)}%</strong><span>complete</span></div></section><div class="va-progress"><i style="width:${Number(d.workspace.setup_progress||0)}%"></i></div><div class="va-journey-list">${cards}</div><div class="va-form-actions">${pending?`<a class="va-button" href="${routeUrl(pending.route,true)}">Continue setup</a>`:`<button class="va-button" type="button" id="finish-setup">Finish setup</button>`}<a class="va-button ghost" href="${routeUrl("dashboard")}">Dashboard</a></div>`;
    document.querySelector("#finish-setup")?.addEventListener("click",async event=>{event.currentTarget.disabled=true;try{await call("verityai_saas.api.onboarding.finish",{workspace});alert("Workspace setup complete.");location.assign(routeUrl("dashboard"));}catch(err){alert(err.message,true);event.currentTarget.disabled=false;}});
  }

  async function assistant() {
    const d = await call("verityai_saas.api.assistant.get", {workspace});
    const natures=d.business_natures||[];
    const options=natures.map(row=>({value:row.business_nature,label:row.business_nature}));
    content.innerHTML = `<form id="assistant-form" class="va-card va-form va-form-card"><div class="va-card-heading"><div><p class="eyebrow">Assistant</p><h2>Identity &amp; sales profile</h2></div></div><div class="va-fields">${field("Assistant name","assistant_name",d.assistant_name)}${field("Brand name","brand_name",d.brand_name)}${selectField("Business nature","business_nature",options,d.business_nature,"Select your industry",true)}${field("Welcome greeting","widget_greeting",d.widget_greeting,"textarea",true)}</div><div id="nature-profile">${natureProfile(d.business_nature,natures)}</div><div class="va-form-actions"><button class="va-button">Save changes</button></div></form>`;
    document.querySelector('#assistant-form [name="business_nature"]').addEventListener("change",event=>{document.querySelector("#nature-profile").innerHTML=natureProfile(event.target.value,natures);});
    bind("assistant-form", async f => call("verityai_saas.api.assistant.update", {workspace, values:json(f)}), null, "widget");
    showGuidedNav();
  }

  async function widget() {
    const d = await call("verityai_saas.api.widget.get", {workspace});
    content.innerHTML = `<form id="widget-form" class="va-card va-form"><h2>Widget appearance</h2><div class="va-fields">${field("Widget title","widget_title",d.widget_title)}${field("Greeting","widget_greeting",d.widget_greeting)}${field("Primary preset","widget_primary_color",d.widget_primary_color)}${field("Header preset","widget_header_color",d.widget_header_color)}</div><button class="va-button">Save appearance</button></form><form id="domain-form" class="va-card va-form"><h2>Allowed domains</h2>${field("One domain per line","domains",(d.allowed_domains||[]).join("\n"),"textarea",true)}<button class="va-button">Save domains</button></form><div class="va-card"><h2>Embed code</h2><pre class="va-code">${esc(d.embed_code)}</pre><p class="muted">Add this before your website's closing body tag. It uses the hardened Verity AI widget runtime.</p></div>`;
    bind("widget-form", f => call("verityai_saas.api.widget.update", {workspace, values:json(f)}));
    bind("domain-form", f => call("verityai_saas.api.widget.set_domains", {workspace, domains:f.domains.value.split(/\r?\n/).filter(Boolean)}), null, "knowledge");
    showGuidedNav();
  }

  async function knowledge() {
    const [sources, ingestions] = await Promise.all([
      call("verityai_saas.api.knowledge.list_sources", {workspace}),
      call("verityai_saas.api.knowledge.ingestion_status", {workspace})
    ]);
    content.innerHTML = `<div class="va-grid three"><form id="knowledge-text-form" class="va-card va-form"><h2>Add text</h2><div class="va-fields">${field("Title","title")}${field("Content","content","","textarea",true)}</div><button class="va-button">Add</button></form><form id="knowledge-file-form" class="va-card va-form"><h2>Upload file</h2><div class="va-fields">${field("Title","title")}<div class="va-field"><label>Private file</label><input type="file" name="file" required accept=".txt,.md,.csv,.json,.html,.htm,.pdf,.docx,.png,.jpg,.jpeg"></div></div><button class="va-button">Upload</button></form><form id="knowledge-url-form" class="va-card va-form"><h2>Add website</h2><div class="va-fields">${field("Title","title")}${field("Public URL","url","","url")}</div><button class="va-button">Add</button></form></div><h2>Processing</h2>${table([["Source",r=>`<strong>${esc(r.title)}</strong><br><span class="muted">${esc(r.source_type)}</span>`],["Status",r=>pill(r.status)],["Processed",r=>`${number(r.pages_processed)} page(s)`],["Updated",r=>esc(r.last_refreshed_on||"—")],["Details",r=>esc(r.error||r.source_url||r.file_url||"—")],["Action",r=>r.source_type==="URL"?`<button class="va-button secondary" data-refresh-ingestion="${esc(r.name)}">Refresh</button>`:"—"]],ingestions)}<h2>Sources</h2>${table([["Source",r=>esc(r.title)],["Status",r=>pill(r.active?"Active":"Inactive")],["Chunks",r=>number(r.chunk_count)],["Updated",r=>esc(r.modified)]],sources)}`;
    bind("knowledge-text-form",form=>call("verityai_saas.api.knowledge.create",{workspace,...json(form)}),knowledge,"email");
    bind("knowledge-url-form",form=>call("verityai_saas.api.knowledge.ingest_url",{workspace,...json(form)}),knowledge,"email");
    document.querySelector("#knowledge-file-form").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget;const button=form.querySelector("button");button.disabled=true;try{const fileName=await uploadPrivateFile(form.file.files[0]);await call("verityai_saas.api.knowledge.ingest_file",{workspace,title:form.title.value,file:fileName});alert("File queued for ingestion.");await knowledge();}catch(err){alert(err.message,true);button.disabled=false;}});
    document.querySelectorAll("[data-refresh-ingestion]").forEach(button=>button.addEventListener("click",async()=>{button.disabled=true;try{await call("verityai_saas.api.knowledge.refresh",{workspace,ingestion_name:button.dataset.refreshIngestion});alert("Refresh queued.");await knowledge();}catch(err){alert(err.message,true);button.disabled=false;}}));
    showGuidedNav();
  }
  async function leads() {
    const [data, assignees] = await Promise.all([
      call("verityai_saas.api.leads.list_leads", {workspace, ...leadFilters}),
      call("verityai_saas.api.leads.assignees", {workspace})
    ]);
    const rows=data.rows||[]; const funnel=data.funnel||{counts:{}};
    const exportQuery=new URLSearchParams({workspace,status:leadFilters.status,source_channel:leadFilters.source_channel,search:leadFilters.search});
    content.innerHTML = `<div class="va-grid"><div class="va-card va-metric"><span>Total leads</span><strong>${number(funnel.total)}</strong></div><div class="va-card va-metric"><span>Qualified rate</span><strong>${number(funnel.qualified_rate)}%</strong></div><div class="va-card va-metric"><span>Win rate</span><strong>${number(funnel.win_rate)}%</strong></div></div><form id="lead-filter" class="va-card va-form"><div class="va-fields">${field("Search name, email or phone","search",leadFilters.search)}<div class="va-field"><label>Status</label><select name="status"><option value="">All</option>${["New","Contacted","Qualified","Won","Lost"].map(value=>`<option ${leadFilters.status===value?"selected":""}>${value}</option>`).join("")}</select></div><div class="va-field"><label>Channel</label><select name="source_channel"><option value="">All</option>${["Web","WhatsApp","Desk"].map(value=>`<option ${leadFilters.source_channel===value?"selected":""}>${value}</option>`).join("")}</select></div></div><div class="va-actions"><button class="va-button">Apply</button><a class="va-button secondary" href="/api/method/verityai_saas.api.leads.export_csv?${exportQuery}">Export CSV</a></div></form>${table([["Lead",r=>`<strong>${esc(r.lead_name)}</strong><br><span class="muted">${esc(r.email||r.phone||"")}</span>`],["Channel",r=>esc(r.source_channel)],["Status",r=>pill(r.status)],["Owner",r=>esc(r.assigned_to||"Unassigned")],["Notes",r=>number(r.note_count)],["Captured",r=>esc(r.creation)],["Actions",r=>`<div class="va-actions"><button class="va-button secondary" data-lead-status="${esc(r.name)}" data-current-status="${esc(r.status)}">Status</button><button class="va-button secondary" data-lead-assign="${esc(r.name)}" data-assigned="${esc(r.assigned_to||"")}">Assign</button><button class="va-button secondary" data-lead-note="${esc(r.name)}">Note</button></div>`]],rows)}<div class="va-actions"><button class="va-button secondary" id="leads-prev" ${leadFilters.start<=0?"disabled":""}>Previous</button><button class="va-button secondary" id="leads-next" ${data.has_more?"":"disabled"}>Next</button></div>`;
    document.querySelector("#lead-filter").addEventListener("submit",event=>{event.preventDefault();leadFilters={...leadFilters,...json(event.currentTarget),start:0};leads();});
    document.querySelector("#leads-prev").addEventListener("click",()=>{leadFilters.start=Math.max(leadFilters.start-leadFilters.limit,0);leads();});
    document.querySelector("#leads-next").addEventListener("click",()=>{leadFilters.start+=leadFilters.limit;leads();});
    document.querySelectorAll("[data-lead-status]").forEach(button=>button.addEventListener("click",async()=>{const status=window.prompt("New status: New, Contacted, Qualified, Won, or Lost",button.dataset.currentStatus);if(!status)return;const note=window.prompt("Optional status note","")||"";try{await call("verityai_saas.api.leads.update_status",{workspace,lead:button.dataset.leadStatus,status,note});alert("Lead status updated.");await leads();}catch(err){alert(err.message,true);}}));
    document.querySelectorAll("[data-lead-assign]").forEach(button=>button.addEventListener("click",async()=>{const assigned=window.prompt(`Assign to an active workspace member:\n${assignees.join("\n")}`,button.dataset.assigned);if(assigned===null)return;const note=window.prompt("Optional assignment note","")||"";try{await call("verityai_saas.api.leads.assign",{workspace,lead:button.dataset.leadAssign,assigned_to:assigned,note});alert("Lead assignment updated.");await leads();}catch(err){alert(err.message,true);}}));
    document.querySelectorAll("[data-lead-note]").forEach(button=>button.addEventListener("click",async()=>{const note=window.prompt("Lead note","");if(!note)return;try{await call("verityai_saas.api.leads.add_note",{workspace,lead:button.dataset.leadNote,note});alert("Lead note added.");await leads();}catch(err){alert(err.message,true);}}));
  }
  async function conversations() {
    const [data, assignees] = await Promise.all([
      call("verityai_saas.api.conversations.list_conversations", {workspace, ...conversationFilters}),
      call("verityai_saas.api.conversations.assignees", {workspace})
    ]);
    const rows=data.rows||[];
    const exportQuery=new URLSearchParams({workspace,platform:conversationFilters.platform,status:conversationFilters.status,search:conversationFilters.search});
    content.innerHTML = `<form id="conversation-filter" class="va-card va-form"><div class="va-fields">${field("Search session or visitor","search",conversationFilters.search)}<div class="va-field"><label>Platform</label><select name="platform"><option value="">All</option>${["Web","WhatsApp","Desk"].map(value=>`<option ${conversationFilters.platform===value?"selected":""}>${value}</option>`).join("")}</select></div><div class="va-field"><label>Status</label><select name="status"><option value="">All</option>${["Open","Human Handoff","Closed"].map(value=>`<option ${conversationFilters.status===value?"selected":""}>${value}</option>`).join("")}</select></div></div><div class="va-actions"><button class="va-button">Apply</button><a class="va-button secondary" href="/api/method/verityai_saas.api.conversations.export_csv?${exportQuery}">Export CSV</a></div></form>${table([["Conversation",r=>`<strong>${esc(r.name)}</strong><br><span class="muted">${esc(r.user_identifier||"")}</span>`],["Platform",r=>esc(r.platform)],["Status",r=>pill(r.status)],["Handoff",r=>r.handoff?`${pill(r.handoff.status)}<br><span class="muted">${esc(r.handoff.assigned_to||"Unassigned")}</span>`:"—"],["Updated",r=>esc(r.modified)],["Actions",r=>`<div class="va-actions"><button class="va-button secondary" data-handoff-open="${esc(r.name)}">Open</button><button class="va-button secondary" data-handoff-assign="${esc(r.name)}" data-assigned="${esc(r.handoff?.assigned_to||"")}">Assign</button><button class="va-button" data-handoff-resolve="${esc(r.name)}">Resolve</button></div>`]],rows)}<div class="va-actions"><button class="va-button secondary" id="conversations-prev" ${conversationFilters.start<=0?"disabled":""}>Previous</button><button class="va-button secondary" id="conversations-next" ${data.has_more?"":"disabled"}>Next</button></div>`;
    document.querySelector("#conversation-filter").addEventListener("submit",event=>{event.preventDefault();conversationFilters={...conversationFilters,...json(event.currentTarget),start:0};conversations();});
    document.querySelector("#conversations-prev").addEventListener("click",()=>{conversationFilters.start=Math.max(conversationFilters.start-conversationFilters.limit,0);conversations();});
    document.querySelector("#conversations-next").addEventListener("click",()=>{conversationFilters.start+=conversationFilters.limit;conversations();});
    document.querySelectorAll("[data-handoff-open]").forEach(button=>button.addEventListener("click",async()=>{const note=window.prompt("Why does this conversation need a person?","");if(note===null)return;try{await call("verityai_saas.api.conversations.update_handoff",{workspace,conversation:button.dataset.handoffOpen,status:"Open",note});alert("Handoff opened.");await conversations();}catch(err){alert(err.message,true);}}));
    document.querySelectorAll("[data-handoff-assign]").forEach(button=>button.addEventListener("click",async()=>{const assigned=window.prompt(`Assign to:\n${assignees.join("\n")}`,button.dataset.assigned);if(!assigned)return;const note=window.prompt("Assignment note","")||"";try{await call("verityai_saas.api.conversations.update_handoff",{workspace,conversation:button.dataset.handoffAssign,status:"Assigned",assigned_to:assigned,note});alert("Handoff assigned.");await conversations();}catch(err){alert(err.message,true);}}));
    document.querySelectorAll("[data-handoff-resolve]").forEach(button=>button.addEventListener("click",async()=>{const note=window.prompt("Resolution note","");if(note===null)return;try{await call("verityai_saas.api.conversations.update_handoff",{workspace,conversation:button.dataset.handoffResolve,status:"Resolved",note});alert("Handoff resolved.");await conversations();}catch(err){alert(err.message,true);}}));
  }
  async function crm() {
    const [leadData,customers,pipeline,appointments,activities] = await Promise.all([
      call("verityai_saas.api.leads.list_leads",{workspace,start:0,limit:100}), call("verityai_saas.api.commerce.customers",{workspace}),
      call("verityai_saas.api.commerce.opportunities",{workspace}), call("verityai_saas.api.commerce.appointments",{workspace}),
      call("verityai_saas.api.commerce.activities",{workspace})
    ]);
    const leads=leadData.rows||[], opportunities=pipeline.rows||[];
    const customerOptions=customers.filter(r=>r.status==="Active").map(r=>`<option value="${esc(r.name)}">${esc(r.customer_name)}</option>`).join("");
    const opportunityOptions=opportunities.map(r=>`<option value="${esc(r.name)}">${esc(r.opportunity_name)}</option>`).join("");
    const nextStage={New:"Qualified",Qualified:"Proposal",Proposal:"Negotiation",Negotiation:"Won"};
    content.innerHTML=`<div class="va-grid"><div class="va-card va-metric"><span>Open pipeline</span><strong>${number(pipeline.open_value)}</strong></div><div class="va-card va-metric"><span>Won value</span><strong>${number(pipeline.won_value)}</strong></div><div class="va-card va-metric"><span>Appointments</span><strong>${number(appointments.filter(r=>["Scheduled","Confirmed"].includes(r.status)).length)}</strong></div><div class="va-card va-metric"><span>Follow-ups</span><strong>${number(activities.filter(r=>r.status==="Open").length)}</strong></div></div><div class="va-grid two"><form id="crm-opportunity" class="va-card va-form"><h2>Add opportunity</h2><div class="va-fields">${field("Opportunity name","opportunity_name")}<div class="va-field"><label>Customer</label><select name="customer" required><option value="">Choose customer</option>${customerOptions}</select></div>${field("Expected value","amount",0,"number")}${field("Currency","currency","USD")}${field("Probability %","probability",10,"number")}${field("Expected close","expected_close_date","","date")}${field("Next follow-up","next_follow_up_on","","datetime-local")}${field("Notes","notes","","textarea",true)}</div><button class="va-button" ${customers.length?"":"disabled"}>Save opportunity</button></form><form id="crm-appointment" class="va-card va-form"><h2>Schedule appointment</h2><div class="va-fields">${field("Subject","subject")}<div class="va-field"><label>Customer</label><select name="customer" required><option value="">Choose customer</option>${customerOptions}</select></div><div class="va-field"><label>Opportunity</label><select name="opportunity"><option value="">None</option>${opportunityOptions}</select></div>${field("Starts","starts_on","","datetime-local")}${field("Ends","ends_on","","datetime-local")}<div class="va-field"><label>Mode</label><select name="mode"><option>Online</option><option>Phone</option><option>Onsite</option></select></div>${field("Location / meeting details","location")}${field("Meeting URL","meeting_url","","url")}${field("Notes","notes","","textarea",true)}</div><button class="va-button" ${customers.length?"":"disabled"}>Schedule</button></form><form id="crm-activity" class="va-card va-form"><h2>Log activity or follow-up</h2><div class="va-fields"><div class="va-field"><label>Type</label><select name="activity_type"><option>Call</option><option>Email</option><option>Meeting</option><option>Note</option><option>Follow-up</option></select></div>${field("Subject","subject")}<div class="va-field"><label>Customer</label><select name="customer" required><option value="">Choose customer</option>${customerOptions}</select></div><div class="va-field"><label>Opportunity</label><select name="opportunity"><option value="">None</option>${opportunityOptions}</select></div>${field("Scheduled on","scheduled_on","","datetime-local")}${field("Details","details","","textarea",true)}<label><input type="checkbox" name="completed"> Already completed</label></div><button class="va-button" ${customers.length?"":"disabled"}>Save activity</button></form><div class="va-card"><h2>Pipeline stages</h2>${Object.entries(pipeline.counts||{}).map(([stage,count])=>`<p>${pill(stage)} <strong>${number(count)}</strong> · ${number(pipeline.values?.[stage])}</p>`).join("")}</div></div><h2>AI leads and conversion</h2>${table([["Lead",r=>`<strong>${esc(r.lead_name)}</strong><br><span class="muted">${esc(r.email||r.phone||"")}</span>`],["Status",r=>pill(r.status)],["Channel",r=>esc(r.source_channel)],["Action",r=>`<button class="va-button" data-convert-lead="${esc(r.name)}" ${["Won","Lost"].includes(r.status)?"disabled":""}>Convert</button>`]],leads)}<h2>Opportunities</h2>${table([["Opportunity",r=>`<strong>${esc(r.opportunity_name)}</strong><br><span class="muted">${esc(customers.find(c=>c.name===r.customer)?.customer_name||"")}</span>`],["Stage",r=>pill(r.stage)],["Value",r=>`${esc(r.currency)} ${number(r.amount)}`],["Probability",r=>`${number(r.probability)}%`],["Follow-up",r=>esc(r.next_follow_up_on||"—")],["Action",r=>nextStage[r.stage]?`<div class="va-actions"><button class="va-button" data-opportunity-stage="${esc(r.name)}" data-next="${nextStage[r.stage]}">Move to ${esc(nextStage[r.stage])}</button><button class="va-button danger" data-opportunity-stage="${esc(r.name)}" data-next="Lost">Lost</button></div>`:"—"]],opportunities)}<h2>Appointments</h2>${table([["Appointment",r=>`<strong>${esc(r.subject)}</strong><br><span class="muted">${esc(r.mode)}</span>`],["When",r=>esc(r.starts_on)],["Status",r=>pill(r.status)],["Assigned",r=>esc(r.assigned_to||"Unassigned")],["Action",r=>["Scheduled","Confirmed"].includes(r.status)?`<div class="va-actions"><button class="va-button" data-appointment-status="${esc(r.name)}" data-next="Completed">Complete</button><button class="va-button danger" data-appointment-status="${esc(r.name)}" data-next="Cancelled">Cancel</button></div>`:"—"]],appointments)}<h2>Activity history</h2>${table([["Activity",r=>`<strong>${esc(r.subject)}</strong><br><span class="muted">${esc(r.details||"")}</span>`],["Type",r=>esc(r.activity_type)],["Status",r=>pill(r.status)],["Scheduled",r=>esc(r.scheduled_on||"—")],["Created",r=>esc(r.creation)],["Action",r=>r.status==="Open"?`<button class="va-button" data-activity-complete="${esc(r.name)}">Complete</button>`:"—"]],activities)}`;
    bind("crm-opportunity",form=>call("verityai_saas.api.commerce.save_opportunity",{workspace,values:{...json(form),stage:"New"}}),crm);
    bind("crm-appointment",form=>call("verityai_saas.api.commerce.save_appointment",{workspace,values:{...json(form),status:"Scheduled"}}),crm);
    bind("crm-activity",form=>{const values=json(form);values.status=form.completed.checked?"Completed":"Open";return call("verityai_saas.api.commerce.save_activity",{workspace,values});},crm);
    document.querySelectorAll("[data-convert-lead]").forEach(button=>button.onclick=async()=>{const amount=window.prompt("Expected opportunity value","0");if(amount===null)return;button.disabled=true;try{await call("verityai_saas.api.commerce.convert_lead",{workspace,lead:button.dataset.convertLead,values:{amount}});alert("Lead converted to customer and opportunity.");await crm();}catch(err){alert(err.message,true);button.disabled=false;}});
    document.querySelectorAll("[data-opportunity-stage]").forEach(button=>button.onclick=async()=>{let reason="";if(button.dataset.next==="Lost"){reason=window.prompt("Why was this opportunity lost?","");if(!reason)return;}button.disabled=true;try{await call("verityai_saas.api.commerce.set_opportunity_stage",{workspace,opportunity:button.dataset.opportunityStage,stage:button.dataset.next,lost_reason:reason});await crm();}catch(err){alert(err.message,true);button.disabled=false;}});
    document.querySelectorAll("[data-appointment-status]").forEach(button=>button.onclick=async()=>{const outcome=window.prompt("Outcome / reason","")||"";button.disabled=true;try{await call("verityai_saas.api.commerce.set_appointment_status",{workspace,appointment:button.dataset.appointmentStatus,status:button.dataset.next,outcome});await crm();}catch(err){alert(err.message,true);button.disabled=false;}});
    document.querySelectorAll("[data-activity-complete]").forEach(button=>button.onclick=async()=>{button.disabled=true;try{await call("verityai_saas.api.commerce.set_activity_status",{workspace,activity:button.dataset.activityComplete,status:"Completed"});await crm();}catch(err){alert(err.message,true);button.disabled=false;}});
  }
  async function commerce() {
    const [customers,products,quotations] = await Promise.all([
      call("verityai_saas.api.commerce.customers",{workspace}),
      call("verityai_saas.api.commerce.products",{workspace}),
      call("verityai_saas.api.commerce.quotations",{workspace})
    ]);
    const productOptions=products.filter(row=>row.active).map(row=>`<option value="${esc(row.name)}">${esc(row.item_code)} — ${esc(row.item_name)}</option>`).join("");
    const customerOptions=customers.filter(row=>row.status==="Active").map(row=>`<option value="${esc(row.name)}">${esc(row.customer_name)}</option>`).join("");
    const action=(label,panel,kind="secondary")=>`<button type="button" class="va-button ${kind}" data-commerce-open="${panel}">${label}</button>`;
    const line=()=>`<div class="va-quote-line"><div class="va-field va-line-product"><label>Product</label><select name="product" required><option value="">Choose product</option>${productOptions}</select></div>${field("Quantity","qty",1,"number")}${field("Unit price override","rate","","number")}${field("Discount %","discount_percent",0,"number")}<button type="button" class="va-icon-button danger" data-remove-line aria-label="Remove quotation line">×</button></div>`;
    const customerTable=table([["Customer",r=>`<strong>${esc(r.customer_name)}</strong><br><span class="muted">${esc(r.email||r.phone||"No contact details")}</span>`],["Type",r=>esc(r.customer_type)],["Status",r=>pill(r.status)],["Updated",r=>esc(r.modified)]],customers,{title:"No customers yet",description:"Add your first customer to start building quotations.",action:action("Add customer","customer")});
    const productTable=table([["Product or service",r=>`<strong>${esc(r.item_name)}</strong><br><span class="muted">${esc(r.item_code)}</span>`],["Selling price",r=>`<strong>${esc(r.currency)} ${number(r.standard_rate)}</strong>`],["Unit",r=>esc(r.stock_uom)],["Status",r=>pill(r.active?"Active":"Disabled")],["Action",r=>`<button type="button" class="va-button ghost" data-commerce-open="product" data-product-edit="${esc(r.name)}">Edit</button>`]],products,{title:"Your catalogue is empty",description:"Add your first product or service with its selling price.",action:action("Add product","product")});
    const quoteActions=r=>`<div class="va-actions compact"><a class="va-button ghost" href="/api/method/verityai_saas.api.commerce.download_quotation?workspace=${encodeURIComponent(workspace)}&quotation=${encodeURIComponent(r.name)}">PDF</a>${r.status==="Draft"?`<button class="va-button secondary" data-quote-status="${esc(r.name)}" data-next="Pending Approval">Submit</button>`:""}${r.status==="Pending Approval"?`<button class="va-button secondary" data-quote-status="${esc(r.name)}" data-next="Approved">Approve</button>`:""}${r.status==="Approved"?`<button class="va-button secondary" data-quote-status="${esc(r.name)}" data-next="Sent">Mark sent</button>`:""}</div>`;
    const quoteTable=table([["Quotation",r=>`<strong>${esc(r.name)}</strong><br><span class="muted">${esc(r.customer_name)}</span>`],["Date",r=>esc(r.transaction_date)],["Total",r=>`${esc(r.currency)} ${number(r.total)}`],["Status",r=>pill(r.status)],["Actions",quoteActions]],quotations,{title:"No quotations yet",description:"Create a customer and product before preparing your first quotation.",action:customers.length&&products.length?action("New quotation","quote","primary"):""});
    const views={
      overview:`<div class="va-grid va-metrics"><div class="va-card va-metric"><span>Customers</span><strong>${number(customers.length)}</strong><small>${number(customers.filter(row=>row.status==="Active").length)} active</small></div><div class="va-card va-metric"><span>Products & services</span><strong>${number(products.length)}</strong><small>${number(products.filter(row=>row.active).length)} ready to quote</small></div><div class="va-card va-metric"><span>Quotations</span><strong>${number(quotations.length)}</strong><small>${number(quotations.filter(row=>row.status==="Draft").length)} drafts</small></div><div class="va-card va-metric"><span>Quoted value</span><strong>${number(quotations.reduce((sum,row)=>sum+Number(row.total||0),0))}</strong><small>Across all quotations</small></div>${section("Recent quotations","Your latest commercial activity.",table([["Quotation",r=>`<strong>${esc(r.name)}</strong><br><span class="muted">${esc(r.customer_name)}</span>`],["Total",r=>`${esc(r.currency)} ${number(r.total)}`],["Status",r=>pill(r.status)],["Actions",quoteActions]],quotations.slice(0,5),{title:"No commercial activity yet",description:"Add a customer and product to prepare your first quotation."}),customers.length&&products.length?action("New quotation","quote","primary"):"")}</div>`,
      customers:section("Customers","Organisations and contacts you sell to.",customerTable,action("Add customer","customer","primary")),
      products:section("Products & services","Your catalogue, units and selling prices in one place.",productTable,action("Add product","product","primary")),
      quotations:section("Quotations","Prepare, approve, download and track customer proposals.",quoteTable,customers.length&&products.length?action("New quotation","quote","primary"):"")
    };
    const drawer=(name,title,description,form)=>`<section class="va-drawer-panel" data-commerce-panel="${name}" hidden><header class="va-drawer-heading"><div><p class="eyebrow">Commerce</p><h2>${title}</h2><p>${description}</p></div><button type="button" class="va-icon-button" data-commerce-close aria-label="Close">×</button></header>${form}</section>`;
    const customerForm=`<form id="commerce-customer" class="va-form"><div class="va-fields">${field("Customer name","customer_name")}${field("Email","email","","email")}${field("Phone","phone")}${field("Tax ID","tax_id")}${field("Address","address","","textarea",true)}</div><div class="va-form-actions"><button type="button" class="va-button ghost" data-commerce-close>Cancel</button><button class="va-button">Save customer</button></div></form>`;
    const productForm=`<form id="commerce-product" class="va-form"><input type="hidden" name="product"><div class="va-fields">${field("Item code","item_code")}${field("Item name","item_name")}${field("Selling price","standard_rate",0,"number")}${field("Currency","currency","USD")}${field("Unit of measure","stock_uom","Unit")}${field("Category","item_group","Services")}<label class="va-check full"><input type="checkbox" name="is_stock_item"> This is a stocked physical item</label>${field("Description","description","","textarea",true)}</div><div class="va-form-actions"><button type="button" class="va-button ghost" data-commerce-close>Cancel</button><button class="va-button">Save product</button></div></form>`;
    const quoteForm=`<form id="commerce-quote" class="va-form"><div class="va-fields"><div class="va-field full"><label>Customer</label><select name="customer" required><option value="">Choose customer</option>${customerOptions}</select></div>${field("Quotation date","transaction_date",new Date().toISOString().slice(0,10),"date")}${field("Valid until","valid_till","","date")}${field("Currency","currency","USD")}${field("Additional discount","discount_amount",0,"number")}${field("Tax rate %","tax_rate",0,"number")}${field("Notes","notes","","textarea",true)}</div><div class="va-subsection-heading"><div><h3>Line items</h3><p>Product selling prices are applied automatically. Override a line only when this quotation needs a special price.</p></div><button type="button" class="va-button ghost" id="add-quote-line">+ Add item</button></div><div id="quote-lines">${line()}</div><div class="va-form-actions"><button type="button" class="va-button ghost" data-commerce-close>Cancel</button><button class="va-button" ${customers.length&&products.length?"":"disabled"}>Save draft</button></div></form>`;
    content.innerHTML=`<div class="va-command-bar"><div><h2>Sales workspace</h2><p>Customers, products and quotations in one clean workflow.</p></div><div class="va-actions">${action("Add customer","customer")}${action("Add product","product")}${customers.length&&products.length?action("New quotation","quote","primary"):""}</div></div><div class="va-tabs" role="tablist">${[["overview","Overview"],["customers","Customers"],["products","Products"],["quotations","Quotations"]].map(([key,label])=>`<button type="button" role="tab" aria-selected="${commerceView===key}" class="${commerceView===key?"active":""}" data-commerce-view="${key}">${label}</button>`).join("")}</div><div class="va-commerce-view">${views[commerceView]||views.overview}</div><div class="va-drawer-backdrop" hidden><aside class="va-drawer" role="dialog" aria-modal="true">${drawer("customer","Add customer","Create a customer record for sales and quotation workflows.",customerForm)}${drawer("product","Product details","Manage the product or service and its selling price together.",productForm)}${drawer("quote","Create quotation","Prepare a customer proposal without leaving the Commerce workspace.",quoteForm)}</aside></div>`;
    const backdrop=document.querySelector(".va-drawer-backdrop");
    const closeDrawer=()=>{backdrop.hidden=true;document.body.classList.remove("va-no-scroll");backdrop.querySelectorAll("[data-commerce-panel]").forEach(panel=>panel.hidden=true);};
    document.querySelectorAll("[data-commerce-open]").forEach(button=>button.onclick=()=>{const panel=backdrop.querySelector(`[data-commerce-panel="${button.dataset.commerceOpen}"]`);const form=panel.querySelector("form");form?.reset();if(button.dataset.productEdit){const product=products.find(row=>row.name===button.dataset.productEdit);if(product){form.product.value=product.name;["item_code","item_name","standard_rate","currency","stock_uom","item_group","description"].forEach(name=>{if(form[name])form[name].value=product[name]??"";});form.is_stock_item.checked=Boolean(product.is_stock_item);}}panel.hidden=false;backdrop.hidden=false;document.body.classList.add("va-no-scroll");window.setTimeout(()=>panel.querySelector('input:not([type="hidden"]), select, textarea')?.focus(),0);});
    document.querySelectorAll("[data-commerce-close]").forEach(button=>button.onclick=closeDrawer);
    backdrop.onclick=event=>{if(event.target===backdrop)closeDrawer();};
    document.onkeydown=event=>{if(event.key==="Escape"&&!backdrop.hidden)closeDrawer();};
    document.querySelectorAll("[data-commerce-view]").forEach(button=>button.onclick=()=>{commerceView=button.dataset.commerceView;commerce();});
    bind("commerce-customer",form=>call("verityai_saas.api.commerce.save_customer",{workspace,values:json(form)}),commerce);
    bind("commerce-product",form=>{const values={...json(form),active:1,is_stock_item:form.is_stock_item.checked?1:0};const product=values.product;delete values.product;return call("verityai_saas.api.commerce.save_product",{workspace,product,values});},commerce);
    const lines=document.querySelector("#quote-lines");
    const bindLineRemoval=()=>document.querySelectorAll("[data-remove-line]").forEach(button=>button.onclick=()=>{if(document.querySelectorAll(".va-quote-line").length>1)button.closest(".va-quote-line").remove();});
    bindLineRemoval(); document.querySelector("#add-quote-line").onclick=()=>{lines.insertAdjacentHTML("beforeend",line());bindLineRemoval();};
    document.querySelector("#commerce-quote").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget;const button=form.querySelector('button[type="submit"],button:not([type])');button.disabled=true;try{const values=json(form);values.items=[...form.querySelectorAll(".va-quote-line")].map(row=>({product:row.querySelector('[name="product"]').value,qty:row.querySelector('[name="qty"]').value,rate:row.querySelector('[name="rate"]').value,discount_percent:row.querySelector('[name="discount_percent"]').value}));await call("verityai_saas.api.commerce.save_quotation",{workspace,values});alert("Quotation draft created.");await commerce();}catch(err){alert(err.message,true);button.disabled=false;}});
    document.querySelectorAll("[data-quote-status]").forEach(button=>button.onclick=async()=>{button.disabled=true;try{await call("verityai_saas.api.commerce.set_quotation_status",{workspace,quotation:button.dataset.quoteStatus,status:button.dataset.next});await commerce();}catch(err){alert(err.message,true);button.disabled=false;}});
  }
  async function quotes() {
    const rows = await call("verityai_saas.api.quotes.list_requests", {workspace});
    const pending = rows.filter(row => row.status === "Pending").length;
    content.innerHTML = `<div class="va-grid two"><div class="va-card va-metric"><span>Pending approval</span><strong>${number(pending)}</strong></div><div class="va-card"><h2>Safe approval flow</h2><p class="muted">Approval submits and sends the existing engine quotation. VerityAI never bypasses the engine approval hook.</p></div></div>${table([["Request",r=>`<strong>${esc(r.name)}</strong><br><span class="muted">${esc(r.erpnext_quotation_id||"Draft quotation")}</span>`],["Customer",r=>`<strong>${esc(r.customer_name)}</strong><br><span class="muted">${esc(r.client_email||r.client_whatsapp_number||"")}</span>`],["Total",r=>number(r.estimated_total)],["Status",r=>pill(r.status)],["Created",r=>esc(r.creation)],["Action",r=>r.status==="Pending"?`<button type="button" class="va-button" data-approve-quote="${esc(r.name)}">Approve &amp; send</button>`:'<span class="muted">Complete</span>']],rows)}`;
    document.querySelectorAll("[data-approve-quote]").forEach(button => button.addEventListener("click", async () => {
      const request = button.dataset.approveQuote;
      if (!window.confirm(`Approve ${request}? This submits the quotation and sends it through the configured engine channel.`)) return;
      const notes = window.prompt("Optional approval note", "") ?? "";
      button.disabled = true;
      try { await call("verityai_saas.api.quotes.approve", {workspace, quotation_request:request, notes}); alert("Quotation approved and processed."); await quotes(); }
      catch (err) { alert(err.message, true); button.disabled = false; }
    }));
  }
  async function usage() {
    const [summary, analytics] = await Promise.all([
      call("verityai_saas.api.usage.get", {workspace, ...analyticsFilters}),
      call("verityai_saas.api.analytics.get", {workspace, ...analyticsFilters})
    ]);
    const exportQuery=new URLSearchParams({workspace,from_date:analytics.from_date,to_date:analytics.to_date});
    const breakdown=(rows,empty)=>Object.entries(rows||{}).length?`<div class="va-breakdown">${Object.entries(rows).map(([key,value])=>`<div><span>${esc(key)}</span><strong>${number(value)}</strong></div>`).join("")}</div>`:emptyState(empty,"Activity will appear here as customers engage with the assistant.");
    content.innerHTML = `<form id="analytics-filter" class="va-filter-bar"><div><p class="eyebrow">Reporting period</p><strong>${esc(analytics.from_date)} to ${esc(analytics.to_date)}</strong></div><div class="va-filter-fields">${field("From","from_date",analytics.from_date,"date")}${field("To","to_date",analytics.to_date,"date")}</div><div class="va-actions"><button class="va-button">Apply</button><a class="va-button secondary" href="/api/method/verityai_saas.api.analytics.export_workspace?${exportQuery}">Export data</a></div></form><div class="va-grid va-metrics"><div class="va-card va-metric"><span>AI credits consumed</span><strong>${number(summary.total_tokens)}</strong><small>Selected period</small></div><div class="va-card va-metric"><span>Estimated AI cost</span><strong>${number(summary.estimated_cost)}</strong><small>Provider estimate</small></div><div class="va-card va-metric"><span>Leads captured</span><strong>${number(analytics.funnel?.total)}</strong><small>Across all channels</small></div><div class="va-card va-metric"><span>Win rate</span><strong>${number(analytics.funnel?.win_rate)}%</strong><small>Converted opportunities</small></div></div>${section("Activity trends","Daily usage and customer engagement across the selected period.",`<div class="va-grid two va-chart-grid">${barChart(analytics.usage,"tokens","Daily AI credits")}${barChart(analytics.usage,"cost","Daily AI cost")}${barChart(analytics.leads,"leads","Daily leads")}${barChart(analytics.conversations,"conversations","Daily conversations")}</div>`)}<div class="va-grid two">${section("Conversations by channel","Where customer interactions originate.",breakdown(analytics.channels,"No conversations yet"))}${section("Lead funnel","Movement through your sales pipeline.",breakdown(analytics.funnel?.counts,"No leads yet"))}</div>`;
    document.querySelector("#analytics-filter").addEventListener("submit",event=>{event.preventDefault();analyticsFilters=json(event.currentTarget);usage();});
  }
  async function billing() {
    const d = await call("verityai_saas.api.billing.get", {workspace}); const s=d.subscription?.[0];
    const paidPlans = (d.plans||[]).filter(plan=>plan.plan_code!=="TRIAL" && (Number(plan.monthly_price)>0 || Number(plan.annual_price)>0));
    const planFeatures=plan=>[`${number(plan.monthly_web_conversations)} website conversations`,`${number(plan.max_team_members)} team member${Number(plan.max_team_members)===1?"":"s"}`,`${number(plan.max_knowledge_sources)} knowledge sources`,plan.can_use_whatsapp_ai?`${number(plan.monthly_whatsapp_messages)} WhatsApp AI replies · Early Access`:"WhatsApp contact button",plan.can_remove_branding?"Remove VerityAI branding":"VerityAI branded",plan.can_use_erpnext_integration?"ERPNext and API integrations":plan.can_use_custom_smtp?"Custom business email":"Email notifications"];
    const plans = paidPlans.map(plan=>`<form class="va-plan-card va-checkout-card ${plan.plan_code==="GROWTH"?"featured":""}" data-paynow-plan="${esc(plan.name)}"><div class="va-plan-card-head"><div><span class="va-plan-label">${plan.plan_code==="GROWTH"?"Most popular":"Subscription plan"}</span><h3>${esc(plan.plan_name)}</h3></div><div class="va-plan-price"><strong>${esc(plan.currency)} ${number(plan.monthly_price)}</strong><small>/ month</small></div></div><p><strong>${number(plan.monthly_token_limit)}</strong> AI credits included monthly</p><ul class="va-plan-features">${planFeatures(plan).map(value=>`<li>${esc(value)}</li>`).join("")}</ul><div class="va-field"><label>Billing cycle</label><select name="billing_cycle"><option value="Monthly">Monthly — ${esc(plan.currency)} ${number(plan.monthly_price)}</option>${Number(plan.annual_price)>0?`<option value="Annual">Annual — ${esc(plan.currency)} ${number(plan.annual_price)} (2 months free)</option>`:""}</select></div><div class="va-field"><label>Promotion code <span class="muted">optional</span></label><input name="promotion_code" maxlength="40" autocomplete="off" placeholder="Enter code"></div><div class="va-checkout-methods"><button class="va-payment-choice card" ${d.paynow_configured?"":"disabled"}><span class="va-choice-icon">PAY</span><span><strong>Continue to secure payment</strong><small>Choose card, mobile money or available local methods</small></span><span class="va-choice-arrow">→</span></button></div><p class="va-checkout-security">We create and verify your order first, then Paynow securely collects payment. Card details never touch VerityAI.</p></form>`).join("");
    const checkout = plans || emptyState("No paid plans available","Contact support to discuss the right plan for your workspace.");
    const canBuyCredits=s?.status==="Active"&&d.paynow_configured;
    const topups=(d.credit_packs||[]).map(pack=>`<form class="va-credit-pack" data-credit-pack="${esc(pack.name)}"><div class="va-credit-pack-copy"><span class="va-plan-label">Prepaid</span><strong>${number(pack.credits)} <span>AI credits</span></strong><small>Unused purchased credits roll over while your paid plan remains active.</small></div><div class="va-credit-pack-action"><strong>${esc(pack.currency)} ${number(pack.price)}</strong>${canBuyCredits?'<button class="va-button">Buy credits</button>':s?.status!=="Active"?'<button type="button" class="va-button secondary" data-plan-required>Choose a plan first</button>':'<button type="button" class="va-button secondary" disabled>Checkout unavailable</button>'}</div></form>`).join("");
    const referralLink=`${location.origin}/verityai/signup?ref=${encodeURIComponent(d.referral?.code||"")}`;
    const referral=`<div class="va-referral-card"><div><p class="eyebrow">VerityAI Rewards</p><h3>Give 25%, earn ${number(d.referral?.reward_credits)} AI credits</h3><p>Your referral receives 25% off their first paid month. Your reward unlocks after their payment remains successful for 14 days.</p></div><div class="va-referral-code"><code>${esc(d.referral?.code||"—")}</code><button type="button" class="va-button secondary" data-copy="${esc(referralLink)}">Copy referral link</button></div></div>`;
    const documents=table([["Document",r=>`<strong>${esc(r.document_number)}</strong><br><span class="muted">${esc(r.document_type)}</span>`],["Amount",r=>`${esc(r.currency||"")} ${number(r.total)}`],["Status",r=>pill(r.status)],["Issued",r=>esc(r.issue_date)],["Download",r=>`<a class="va-button ghost" href="/api/method/verityai_saas.api.billing.download_document?workspace=${encodeURIComponent(workspace)}&document=${encodeURIComponent(r.name)}">Download PDF</a>`]],d.documents||[],{title:"No billing documents",description:"Invoices and receipts will appear here after your first payment."});
    const events=table([["Payment",r=>`<strong>${esc(r.event_type)}</strong><br><span class="muted">${esc(r.provider||"Manual")}</span>`],["Amount",r=>`${esc(r.currency||"")} ${number(r.amount)}`],["Status",r=>`${pill(r.status)} ${r.gateway_status?pill(r.gateway_status):""}`],["Reference",r=>esc(r.gateway_reference||"—")],["Date",r=>esc(r.creation)]],d.events||[],{title:"No payment activity",description:"Secure Paynow transactions will appear here."});
    const inactive=["Expired","Suspended","Cancelled"].includes(s?.status)||Number(d.wallet?.tokens_remaining)<=0;
    content.innerHTML = `<div class="va-plan-hero"><div><p class="eyebrow">Current subscription</p><h2>${esc(s?.plan||"No active plan")}</h2><div class="va-actions">${pill(s?.status||"Not configured")}<span class="muted">${s?.status==="Trial"?`Trial ends ${esc(s?.trial_end||"—")}`:`Next renewal ${esc(s?.next_billing_date||"—")}`}</span></div></div><div class="va-plan-usage"><div><span>AI credits used</span><strong>${number(d.wallet?.tokens_used)}</strong></div><div><span>AI credits remaining</span><strong>${number(d.wallet?.tokens_remaining)}</strong></div></div></div>${inactive?'<div class="va-callout warning"><strong>AI assistant paused</strong><span>Choose a paid plan or add eligible credits to continue serving customers.</span></div>':""}${d.paynow_configured?"":'<div class="va-callout warning"><strong>Online checkout unavailable</strong><span>Paynow is not configured yet. Contact support to activate a plan.</span></div>'}${section("Choose your plan","Predictable monthly access with prepaid AI capacity and no surprise overage bill.",`<div class="va-plan-grid">${checkout}</div>`)}${section("Add AI credits","Need more capacity? Prepaid credits remain available across monthly renewals while the subscription stays active.",`<div class="va-credit-pack-grid">${topups||emptyState("No credit packs available","Additional prepaid capacity will appear here.")}</div>`)}${referral}${section("Invoices & receipts","Download official billing documents for this workspace.",documents)}${section("Payment history","A traceable record of payment, renewal and credit activity.",events)}`;
    document.querySelectorAll("[data-paynow-plan]").forEach(form=>form.addEventListener("submit", async event=>{
      event.preventDefault(); const button=event.submitter || form.querySelector("button"); form.querySelectorAll("button").forEach(item=>item.disabled=true); button.classList.add("loading");
      try { const result=await call("verityai_saas.api.paynow.start",{workspace,plan:form.dataset.paynowPlan,billing_cycle:form.billing_cycle.value,promotion_code:form.promotion_code.value}); window.location.assign(result.checkout_url); }
      catch(err){alert(err.message,true);form.querySelectorAll("button").forEach(item=>item.disabled=false);button.classList.remove("loading");}
    }));
    document.querySelectorAll("[data-credit-pack]").forEach(form=>form.addEventListener("submit",async event=>{event.preventDefault();const button=form.querySelector("button");button.disabled=true;try{const result=await call("verityai_saas.api.paynow.start_credit_top_up",{workspace,credit_pack:form.dataset.creditPack});location.assign(result.checkout_url);}catch(err){alert(err.message,true);button.disabled=false;}}));
    document.querySelectorAll("[data-plan-required]").forEach(button=>button.addEventListener("click",()=>{alert("Activate Launch, Growth or Scale before adding prepaid AI credits.");document.querySelector(".va-plan-grid")?.scrollIntoView({behavior:"smooth",block:"start"});}));
    document.querySelectorAll("[data-copy]").forEach(button=>button.addEventListener("click",()=>navigator.clipboard.writeText(button.dataset.copy).then(()=>alert("Referral link copied."))));
    const payment = new URLSearchParams(location.search).get("payment");
    if(payment){
      try { const result=await call("verityai_saas.api.paynow.poll",{workspace,payment}); alert(result.status==="Completed"?(result.transaction_kind==="Credit Top-Up"?"Payment confirmed and AI credits added.":"Payment confirmed and plan activated."):`Payment status: ${result.gateway_status||result.status}`); history.replaceState({},"",`/verityai/billing?workspace=${encodeURIComponent(workspace)}`); if(result.status==="Completed") window.setTimeout(()=>billing(),400); }
      catch(err){alert(err.message,true);}
    }
  }

  async function email() {
    const [d, deliveryLogs] = await Promise.all([call("verityai_saas.api.email.get", {workspace}), call("verityai_saas.api.email.delivery_logs", {workspace, limit:50})]);
    const toggles = [["lead_notifications_enabled","New lead notifications"],["human_handoff_alerts_enabled","Human handoff alerts"],["quote_request_alerts_enabled","Quotation approval requests"],["usage_warning_alerts_enabled","Usage warnings"],["provider_failure_alerts_enabled","Provider failure alerts"],["daily_summary_enabled","Daily lead summary"]];
    const checks = toggles.map(([name,label])=>`<label><input type="checkbox" name="${name}" ${d[name]?"checked":""}> ${label}</label>`).join("");
    const logs=table([["Delivery",r=>`<strong>${esc(r.subject)}</strong><br><span class="muted">${esc(r.recipient)}</span>`],["Type",r=>esc(r.notification_type)],["Status",r=>pill(r.status)],["Error",r=>esc(r.error||"—")],["Date",r=>esc(r.sent_on||r.creation)],["Action",r=>r.status==="Failed"?`<button type="button" class="va-button secondary" data-retry-email="${esc(r.name)}">Retry</button>`:"—"]],deliveryLogs,{title:"No delivery activity",description:"Notification deliveries will appear here once events occur."});
    content.innerHTML = `<div class="va-status-strip"><div><span class="va-status-dot ${d.status==="Active"?"good":""}"></span><div><strong>Email notifications</strong><p>${d.status==="Active"?"Workspace alerts are enabled.":"Workspace alerts are currently disabled."}</p></div></div><button type="button" id="email-test" class="va-button secondary">Send test email</button></div><form id="email-form" class="va-section va-form-section"><header class="va-section-heading"><div><h2>Notification settings</h2><p>Control sender identity, recipients and the events that reach your team.</p></div>${pill(d.status)}</header><div class="va-settings-block"><h3>Delivery identity</h3><div class="va-fields">${field("Notification email","notification_email",d.notification_email,"email")}${field("Reply-to email","reply_to_email",d.reply_to_email,"email")}${field("Additional recipients","alert_recipients",d.alert_recipients)}${field("Branding name","email_branding_name",d.email_branding_name)}<div class="va-field"><label>Status</label><select name="status"><option ${d.status==="Active"?"selected":""}>Active</option><option ${d.status==="Disabled"?"selected":""}>Disabled</option></select></div>${field("Email footer","email_footer",d.email_footer,"textarea",true)}</div></div><div class="va-settings-block"><h3>Alert subscriptions</h3><p>Select only the events that need a human response.</p><div class="va-check-grid">${checks}</div></div><div class="va-form-actions"><button class="va-button">Save notification settings</button></div></form>${section("Delivery history","Recent notification attempts and any action required.",logs)}`;
    bind("email-form", f => {const v=json(f);toggles.forEach(([key])=>v[key]=f[key].checked?1:0);return call("verityai_saas.api.email.update",{workspace,values:v});}, null, "whatsapp");
    document.querySelectorAll("[data-retry-email]").forEach(button => button.addEventListener("click", async () => {
      button.disabled = true;
      try { await call("verityai_saas.api.email.retry", {workspace, delivery_log:button.dataset.retryEmail}); alert("Failed email delivery retried successfully."); await email(); }
      catch (err) { alert(err.message, true); button.disabled = false; }
    }));
    document.querySelector("#email-test").addEventListener("click", async event => {
      const button = event.currentTarget; button.disabled = true;
      try { const result = await call("verityai_saas.api.email.send_test", {workspace}); alert(`Test email processed for ${result.delivery_logs.length} recipient(s).`); }
      catch (err) { alert(err.message, true); }
      finally { button.disabled = false; }
    });
    showGuidedNav();
  }

  async function whatsapp() {
    const d = await call("verityai_saas.api.whatsapp.get", {workspace});
    const signature=d.engine?.signature_verification_enabled;
    content.innerHTML = `<div class="va-status-strip"><div><span class="va-status-dot ${d.setup_status==="Connected"?"good":""}"></span><div><strong>WhatsApp channel</strong><p>${esc(d.webhook_health?.message||"Configure Meta Cloud API to activate this channel.")}</p></div></div><div class="va-actions">${pill(d.setup_status)}${pill(d.webhook_health?.status||"Not configured")}</div></div><div class="va-operations-grid"><form id="wa-form" class="va-section va-form-section"><header class="va-section-heading"><div><h2>Channel configuration</h2><p>Connect the business number and choose how the assistant participates.</p></div></header><div class="va-settings-block"><h3>Experience</h3><div class="va-fields"><div class="va-field"><label>Mode</label><select name="mode"><option ${d.mode==="Button Only"?"selected":""}>Button Only</option><option ${d.mode==="Lead Alerts"?"selected":""}>Lead Alerts</option><option ${d.mode==="Full AI Automation"?"selected":""}>Full AI Automation</option></select></div>${field("Business WhatsApp number","business_whatsapp_number",d.business_whatsapp_number)}${field("Meta phone number ID","whatsapp_phone_id",d.whatsapp_phone_id)}</div></div><details class="va-secret-panel"><summary>Meta credentials <span>Encrypted and write-only</span></summary><div class="va-fields">${field("Access token","whatsapp_access_token","","password")}${field("Verify token","meta_verify_token","","password")}${field("App secret","meta_app_secret","","password")}</div></details><label class="va-check"><input type="checkbox" name="verify_meta_signature" ${signature?"checked":""}> Verify every Meta webhook signature</label><div class="va-form-actions"><button type="button" id="wa-test" class="va-button secondary">Test connection</button><button class="va-button">Save channel</button></div></form><aside class="va-section va-callback-card"><header class="va-section-heading"><div><h2>Webhook endpoint</h2><p>Add this callback URL in your Meta application.</p></div></header><div class="va-settings-block"><pre class="va-code">${esc(d.engine?.callback_url)}</pre><button type="button" class="va-button ghost" data-copy="${esc(d.engine?.callback_url||"")}">Copy URL</button></div><div class="va-security-list"><div><span>Signature verification</span>${signature?pill("Active"):pill("Required")}</div><div><span>Webhook health</span>${pill(d.webhook_health?.status||"Unknown")}</div></div></aside></div>`;
    content.insertAdjacentHTML("afterbegin", `<div class="va-status-strip"><strong>WhatsApp AI</strong>${pill("Early Access")}</div>`);
    bind("wa-form", f => {const v=json(f);v.verify_meta_signature=f.verify_meta_signature.checked?1:0;return call("verityai_saas.api.whatsapp.update",{workspace,values:v});},whatsapp,"onboarding");
    document.querySelector("#wa-test").addEventListener("click", async event => {
      const button=event.currentTarget; button.disabled=true;
      try { const result=await call("verityai_saas.api.whatsapp.test_connection",{workspace}); alert(`Meta connected${result.verified_name?`: ${result.verified_name}`:""}.`); await whatsapp(); }
      catch(err){alert(err.message,true);button.disabled=false;}
    });
    document.querySelector("[data-copy]").onclick=async event=>{try{await navigator.clipboard.writeText(event.currentTarget.dataset.copy);alert("Callback URL copied.");}catch(err){alert("Copy failed. Select and copy the URL manually.",true);}};
    showGuidedNav();
  }

  async function integrations() {
    const d = await call("verityai_saas.api.integrations.get", {workspace});
    const f=d.features||{}, provider=d.provider||{}, erp=d.erpnext||{}, smtp=d.smtp||{}, paynow=d.paynow||{};
    const disabledCard=(title,flag)=>`<div class="va-card"><h2>${esc(title)}</h2><p class="muted">This feature is not included in the current plan (${esc(flag)}).</p></div>`;
    const providerCard=f.can_bring_own_ai_provider_key?`<form id="provider-form" class="va-card va-form"><h2>AI provider</h2><p class="muted">Secrets are encrypted and never returned. Leave the key blank to retain it.</p><div class="va-fields"><div class="va-field"><label>Provider</label><select name="provider"><option ${provider.provider==="OpenAI"?"selected":""}>OpenAI</option><option ${provider.provider==="OpenAI-Compatible"?"selected":""}>OpenAI-Compatible</option></select></div>${field("Model","model",provider.model)}${field("HTTPS API base URL","base_url",provider.base_url,"url")}${field(`API key${provider.api_key_present?" (configured)":""}`,"api_key","","password")}${field("Embedding model","embedding_model",provider.embedding_model||"text-embedding-3-small")}<label><input type="checkbox" name="semantic_search_enabled" ${provider.semantic_search_enabled?"checked":""}> Enable semantic knowledge search</label></div><button class="va-button">Save provider</button></form>`:disabledCard("AI provider","BYO provider");
    const erpCard=f.can_use_erpnext_integration?`<form id="erp-form" class="va-card va-form"><h2>ERPNext</h2><p class="muted">Only public HTTPS endpoints are accepted. Secrets are write-only.</p><label><input type="checkbox" name="enabled" ${erp.enabled?"checked":""}> Enable integration</label><div class="va-fields">${field("ERPNext URL","url",erp.url,"url")}${field(`API key${erp.api_key_present?" (configured)":""}`,"api_key","","password")}${field(`API secret${erp.api_secret_present?" (configured)":""}`,"api_secret","","password")}</div><button class="va-button">Save ERPNext</button></form>`:disabledCard("ERPNext","ERPNext integration");
    const smtpCard=f.can_use_custom_smtp?`<form id="smtp-form" class="va-card va-form"><h2>Custom SMTP</h2><p class="muted">Ports 465 and 587 only. TLS certificate verification is always enabled.</p><label><input type="checkbox" name="enabled" ${smtp.enabled?"checked":""}> Use custom SMTP</label><div class="va-fields">${field("SMTP host","host",smtp.host)}${field("Port","port",smtp.port||587,"number")}<label><input type="checkbox" ${smtp.use_tls?"checked":""} disabled> STARTTLS is enforced on port 587</label>${field("Username","username",smtp.username)}${field(`Password${smtp.password_present?" (configured)":""}`,"password","","password")}${field("Sender email","sender_email",smtp.sender_email,"email")}</div><button class="va-button">Save SMTP</button></form>`:disabledCard("Custom SMTP","custom SMTP");
    const paynowCard=`<form id="paynow-form" class="va-card va-form"><h2>Paynow billing</h2><p class="muted">Platform-wide credentials. The integration key is encrypted, write-only, and never returned to the browser.</p><p>${pill(paynow.configured?"Connected":"Not configured")} <span class="muted">${esc(paynow.source||"")}</span></p><div class="va-fields">${field("Integration ID","integration_id",paynow.integration_id)}${field(`Integration key${paynow.configured?" (configured)":""}`,"integration_key","","password")}</div><button class="va-button">Save Paynow credentials</button></form>`;
    const rows=d.api_credentials||[];
    const apiCard=f.can_use_api_access?`<div><form id="api-form" class="va-card va-form"><h2>API credentials</h2><p class="muted">Tokens are shown once. Store them securely. Send the token in the X-VerityAI-API-Key header. Available scopes: leads:read and analytics:read.</p><div class="va-fields">${field("Label","label")}${field("Scopes (space-separated)","scopes","leads:read analytics:read")}</div><button class="va-button">Create token</button></form>${table([["Credential",r=>`<strong>${esc(r.label)}</strong><br><code>${esc(r.token_prefix)}...</code>`],["Scopes",r=>esc(r.scopes)],["Status",r=>pill(r.active?"Active":"Revoked")],["Last used",r=>esc(r.last_used_on||"Never")],["Action",r=>r.active?`<button class="va-button danger" data-revoke-api="${esc(r.name)}">Revoke</button>`:"—"]],rows)}</div>`:disabledCard("API credentials","API access");
    content.innerHTML=`<div class="va-grid two">${paynowCard}${providerCard}${erpCard}${smtpCard}${apiCard}</div>`;
    bind("paynow-form",form=>call("verityai_saas.api.integrations.update_paynow",{workspace,values:json(form)}),integrations);
    if(f.can_bring_own_ai_provider_key) bind("provider-form",form=>{const values=json(form);values.semantic_search_enabled=form.semantic_search_enabled.checked?1:0;return call("verityai_saas.api.integrations.update_provider",{workspace,values});},integrations);
    if(f.can_use_erpnext_integration) bind("erp-form",form=>{const values=json(form);values.enabled=form.enabled.checked?1:0;return call("verityai_saas.api.integrations.update_erpnext",{workspace,values});},integrations);
    if(f.can_use_custom_smtp) bind("smtp-form",form=>{const values=json(form);values.enabled=form.enabled.checked?1:0;return call("verityai_saas.api.integrations.update_smtp",{workspace,values});},integrations);
    if(f.can_use_api_access) document.querySelector("#api-form").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget;const result=await call("verityai_saas.api.integrations.create_credential",{workspace,label:form.label.value,scopes:form.scopes.value.split(/\s+/).filter(Boolean)});window.prompt("Copy this token now. It will not be shown again.",result.token);await integrations();});
    document.querySelectorAll("[data-revoke-api]").forEach(button=>button.addEventListener("click",async()=>{if(!confirm("Revoke this API token?"))return;await call("verityai_saas.api.integrations.revoke_credential",{workspace,credential:button.dataset.revokeApi});await integrations();}));
  }
  async function account() {
    const d = await call("verityai_saas.api.account.get", {workspace});
    const capacity = d.workspace_limit ? `${number(d.workspace_count)} of ${number(d.workspace_limit)} workspaces used` : `${number(d.workspace_count)} workspaces · no configured limit`;
    const createPanel = d.can_add_workspace ? `<form id="additional-workspace" class="va-section va-form-section"><header class="va-section-heading"><div><h2>Add workspace</h2><p>Create another isolated assistant under this account.</p></div><span class="va-step-badge">${esc(capacity)}</span></header><div class="va-settings-block"><div class="va-fields">${field("Workspace name","workspace_name")}${field("Business name","business_name")}</div></div><div class="va-form-actions"><button class="va-button">Create workspace</button></div></form>` : `<section class="va-section"><header class="va-section-heading"><div><h2>Workspace capacity</h2><p>${esc(capacity)}</p></div></header><div class="va-callout warning"><strong>Plan limit reached</strong><span>Upgrade your plan before adding another isolated workspace.</span></div></section>`;
    content.innerHTML = `<div class="va-account-hero"><div><p class="eyebrow">Customer account</p><h2>${esc(d.account_name)}</h2><p>${esc(capacity)}</p></div><div><span>Current plan</span><strong>${esc(d.plan||"Not configured")}</strong></div></div><div class="va-operations-grid"><form id="account-form" class="va-section va-form-section"><header class="va-section-heading"><div><h2>Business profile</h2><p>Used for billing, account communication and workspace defaults.</p></div></header><div class="va-settings-block"><div class="va-fields">${field("Billing email","billing_email",d.billing_email,"email")}${field("Phone","phone",d.phone)}${field("Country","country",d.country)}${field("Currency","currency",d.currency)}<div class="va-field"><label>Customer type</label><select name="customer_type">${["SME","Agency","Enterprise"].map(value=>`<option ${d.customer_type===value?"selected":""}>${value}</option>`).join("")}</select></div></div></div><div class="va-form-actions"><button class="va-button">Save business profile</button></div></form>${createPanel}</div>`;
    bind("account-form", form => call("verityai_saas.api.account.update", {workspace, values:json(form)}), account);
    document.querySelector("#additional-workspace")?.addEventListener("submit", async event => {
      event.preventDefault(); const form=event.currentTarget; const button=form.querySelector("button"); button.disabled=true;
      try { const result=await call("verityai_saas.api.onboarding.create", {account:d.name, account_name:d.account_name, ...json(form)}); location.assign(result.onboarding_url||result.dashboard_url); }
      catch(err){alert(err.message,true);button.disabled=false;}
    });
  }
  async function team() {
    const rows = await call("verityai_saas.api.workspace.members", {workspace});
    const roles = ["Viewer","Sales","Support","Admin","Billing Manager"];
    const permissions = [["can_manage_assistant","Assistant"],["can_manage_widget","Widget"],["can_manage_knowledge","Knowledge"],["can_view_leads","View leads"],["can_manage_leads","Manage leads"],["can_view_conversations","View conversations"],["can_manage_conversations","Manage conversations"],["can_manage_billing","Billing"],["can_manage_whatsapp","WhatsApp"],["can_manage_email","Email"],["can_approve_quotes","Approve AI quote requests"],["can_view_customers","View customers"],["can_manage_customers","Manage customers"],["can_view_catalog","View catalogue"],["can_manage_catalog","Manage catalogue"],["can_view_quotes","View SaaS quotes"],["can_manage_quotes","Manage SaaS quotes"]];
    const cards = rows.map(member => {
      const owner = member.workspace_role === "Owner";
      const disabled = member.status !== "Active";
      if (owner) return `<article class="va-member-row"><div class="va-member-avatar">${esc(member.user.slice(0,1).toUpperCase())}</div><div class="va-member-identity"><strong>${esc(member.user)}</strong><span>Workspace owner · Full access</span></div><div class="va-actions">${pill("Owner")} ${pill(member.status)}</div></article>`;
      const roleOptions = roles.map(role=>`<option ${member.workspace_role===role?"selected":""}>${esc(role)}</option>`).join("");
      const checks = permissions.map(([key,label])=>`<label><input type="checkbox" name="${key}" ${member[key]?"checked":""} ${disabled?"disabled":""}> ${esc(label)}</label>`).join("");
      return `<form class="va-member-row va-member-form" data-member-form="${esc(member.name)}"><details><summary><div class="va-member-avatar">${esc(member.user.slice(0,1).toUpperCase())}</div><div class="va-member-identity"><strong>${esc(member.user)}</strong><span>${esc(member.workspace_role)} · Select to manage access</span></div><div class="va-actions">${pill(member.status)}<span class="va-chevron">⌄</span></div></summary><div class="va-member-access"><div class="va-field"><label>Workspace role</label><select name="role" ${disabled?"disabled":""}>${roleOptions}</select></div><div><h4>Permissions</h4><div class="va-check-grid">${checks}</div></div><div class="va-form-actions"><button class="va-button" ${disabled?"disabled":""}>Save access</button>${disabled?'<span class="muted">Invite this email again to reactivate.</span>':`<button type="button" class="va-button danger" data-remove-member="${esc(member.name)}">Remove member</button>`}</div></div></details></form>`;
    }).join("");
    content.innerHTML = `<form id="team-form" class="va-invite-bar"><div><p class="eyebrow">Workspace access</p><strong>Invite a team member</strong><span>Start with a role; refine permissions after they join.</span></div><div class="va-invite-fields">${field("Email address","email","","email")}<div class="va-field"><label>Role</label><select name="role">${roles.map(role=>`<option>${esc(role)}</option>`).join("")}</select></div><button class="va-button">Send invite</button></div></form>${section("Members",`${number(rows.length)} people have access to this workspace.`,`<div class="va-member-list">${cards}</div>`)}`;
    bind("team-form", f => call("verityai_saas.api.workspace.invite",{workspace,...json(f)}),team);
    document.querySelectorAll("[data-member-form]").forEach(form => form.addEventListener("submit", async event => {
      event.preventDefault();
      const button = form.querySelector('button[type="submit"],button:not([type])');
      const permissionValues = Object.fromEntries(permissions.map(([key])=>[key, form[key].checked?1:0]));
      button.disabled = true;
      try { await call("verityai_saas.api.workspace.update", {workspace,member:form.dataset.memberForm,role:form.role.value,permissions:permissionValues}); alert("Member access updated."); await team(); }
      catch (err) { alert(err.message,true); button.disabled = false; }
    }));
    document.querySelectorAll("[data-remove-member]").forEach(button => button.addEventListener("click", async () => {
      if (!window.confirm("Remove this member from the workspace?")) return;
      button.disabled = true;
      try { await call("verityai_saas.api.workspace.remove", {workspace,member:button.dataset.removeMember}); alert("Member removed."); await team(); }
      catch (err) { alert(err.message,true); button.disabled = false; }
    }));
  }
  function bind(id, action, after, nextRoute) { document.querySelector(`#${id}`).addEventListener("submit", async e => {e.preventDefault();const b=e.currentTarget.querySelector('button[type="submit"],button:not([type])');b.disabled=true;try{await action(e.currentTarget);alert("Saved successfully.");if(after)await after();if(nextRoute)continueGuided(nextRoute);}catch(err){alert(err.message,true)}finally{b.disabled=false}}); }

  async function newWorkspace() {
    const params = new URLSearchParams(location.search);
    const natures=await call("verityai_saas.api.assistant.business_natures");
    const options=natures.map(row=>({value:row.business_nature,label:row.business_nature}));
    picker.closest(".va-workspace-context")?.setAttribute("hidden",""); content.innerHTML=`<form id="new-workspace" class="va-card va-form va-form-card va-onboarding-card"><div class="va-card-heading"><div><p class="eyebrow">Workspace</p><h2>Business profile</h2></div></div><div class="va-fields">${field("Account name","account_name",params.get("account_name")||"")}${field("Workspace name","workspace_name",params.get("workspace_name")||"")}${field("Business name","business_name",params.get("business_name")||"")}${selectField("Business nature","business_nature",options,"","Select your industry")}${field("Referral code (optional)","referral_code",params.get("ref")||params.get("referral_code")||"")}</div><div id="nature-profile">${natureProfile("",natures)}</div><div class="va-form-actions"><button class="va-button">Continue</button></div></form>`;
    document.querySelector('#new-workspace [name="business_nature"]').addEventListener("change",event=>{document.querySelector("#nature-profile").innerHTML=natureProfile(event.target.value,natures);});
    bind("new-workspace", async f=>{const d=await call("verityai_saas.api.onboarding.create",json(f));location.href=d.onboarding_url||d.dashboard_url;});
  }

  const renderers={dashboard,health,onboarding,assistant,widget,knowledge,leads,crm,conversations,commerce,quotes,usage,billing,integrations,email,whatsapp,team,account};
  async function init(){try{const params=new URLSearchParams(location.search);const requested=params.get("workspace")||localStorage.getItem("verityai_workspace")||"";const rows=await call("verityai_saas.api.workspace.list_workspaces",requested?{workspace:requested}:{});if(!rows.length){await newWorkspace();return}const current=rows[0];workspace=current.name;picker.textContent=current.business_name||current.workspace_name;document.querySelectorAll(".va-sidebar nav a").forEach(link=>{const route=link.pathname.split("/").filter(Boolean).pop();link.href=routeUrl(route);});localStorage.setItem("verityai_workspace",workspace);await (renderers[page]||dashboard)()}catch(err){content.innerHTML=`<div class="va-card va-empty">${esc(err.message)}</div>`;alert(err.message,true)}}
  init();
})();
